class BankCustomer {
    String name;
    double balance;

    // 1. Constructor: Sets up initial state at birth
    BankCustomer(String name, double openingDeposit) {
        this.name = name;
        this.balance = openingDeposit;
        System.out.println("Constructor: Account created for " + this.name);
    }

    // 2. Method 1: Mutates state during object life
    void deposit(double amount) {
        this.balance += amount;
        System.out.println("Method: Deposited $" + amount);
    }

    // 3. Method 2: Returns data
    double getBalance() {
        return this.balance;
    }
}

public class Main {
    public static void main(String[] args) {
        // Constructor executes ONCE here:
        BankCustomer customer = new BankCustomer("Aarav", 500.0);

        // Methods can be called multiple times:
        customer.deposit(200.0);
        customer.deposit(100.0);

        System.out.println("Final Balance: $" + customer.getBalance());
    }
}

