class Counter {
    int operations = 0;

    Counter() {
        System.out.println("[Created]");
    }

    void tick() {
        operations++;
        System.out.println("Tick: " + operations);
    }
}

public class Main {
    public static void main(String[] args) {
        Counter c = new Counter();
        c.tick();
        c.tick();
        c.tick();
    }
}

